package com.lyra.studio; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; import android.app.Activity; import android.view.WindowManager; @DesignerComponent(version = 1, description = "Extensão para adaptar o WebViewer ao teclado virtual.", category = ComponentCategory.EXTENSION, nonVisible = true, iconName = "images/extension.png") @SimpleObject(external = true) public class AdvancedWebViewer extends AndroidNonvisibleComponent { private Activity activity; public AdvancedWebViewer(ComponentContainer container) { super(container.$form()); this.activity = container.$context(); } @SimpleFunction(description = "Ajusta o layout da janela para que o teclado virtual não cubra o conteúdo do WebViewer.") public void AdaptarTeclado() { /* Define o modo da janela para redimensionar ao abrir o teclado */ activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } }); } @SimpleFunction(description = "Remove a adaptação do teclado, voltando ao comportamento padrão.") public void RemoverAdaptacaoTeclado() { /* Retorna o modo da janela ao padrão */ activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_UNSPECIFIED); } }); } }